struct Node {
    int key, priority;
    Node *left = nullptr, *right = nullptr;
    Node(int k) : key(k), priority(rand()) {}
};
// split t into l (keys < key) and r (keys >= key)
void split(Node* t, int key, Node*& l, Node*& r) {
    if (!t) { l = r = nullptr; return; }
    if (t->key < key) { split(t->right, key, t->right, r); l = t; }
    else              { split(t->left, key, l, t->left);  r = t; }
}
// merge two treaps where every key in a is below every key in b
Node* merge(Node* a, Node* b) {
    if (!a || !b) return a ? a : b;
    if (a->priority > b->priority) { a->right = merge(a->right, b); return a; }
    else                           { b->left  = merge(a, b->left);  return b; }
}
Node* insert(Node* t, int key) {
    Node *l, *r; split(t, key, l, r);
    return merge(merge(l, new Node(key)), r);
}

