import random
class Node:
    def __init__(self, key):
        self.key = key
        self.priority = random.random()
        self.left = self.right = None

def split(t, key):            # returns (keys < key, keys >= key)
    if not t:
        return None, None
    if t.key < key:
        l, r = split(t.right, key)
        t.right = l
        return t, r
    else:
        l, r = split(t.left, key)
        t.left = r
        return l, t

def merge(a, b):              # all keys in a below all keys in b
    if not a or not b:
        return a or b
    if a.priority > b.priority:
        a.right = merge(a.right, b)
        return a
    else:
        b.left = merge(a, b.left)
        return b

def insert(t, key):
    l, r = split(t, key)
    return merge(merge(l, Node(key)), r)

