class Node {
    int key; double priority;
    Node left, right;
    Node(int k) { key = k; priority = Math.random(); }
}
// returns two treaps via a small holder; l has keys < key, r has the rest
Node[] split(Node t, int key) {
    if (t == null) return new Node[]{null, null};
    if (t.key < key) {
        Node[] p = split(t.right, key);
        t.right = p[0];
        return new Node[]{t, p[1]};
    } else {
        Node[] p = split(t.left, key);
        t.left = p[1];
        return new Node[]{p[0], t};
    }
}
Node merge(Node a, Node b) {
    if (a == null || b == null) return a != null ? a : b;
    if (a.priority > b.priority) { a.right = merge(a.right, b); return a; }
    else                         { b.left  = merge(a, b.left);  return b; }
}
Node insert(Node t, int key) {
    Node[] p = split(t, key);
    return merge(merge(p[0], new Node(key)), p[1]);
}

