class Node {
  constructor(key) { this.key = key; this.priority = Math.random(); this.left = null; this.right = null; }
}
function split(t, key) {          // returns [keys < key, keys >= key]
  if (!t) return [null, null];
  if (t.key < key) {
    const [l, r] = split(t.right, key);
    t.right = l;
    return [t, r];
  } else {
    const [l, r] = split(t.left, key);
    t.left = r;
    return [l, t];
  }
}
function merge(a, b) {            // all keys in a below all keys in b
  if (!a || !b) return a || b;
  if (a.priority > b.priority) { a.right = merge(a.right, b); return a; }
  else { b.left = merge(a, b.left); return b; }
}
function insert(t, key) {
  const [l, r] = split(t, key);
  return merge(merge(l, new Node(key)), r);
}
